import React, { useState, useRef } from 'react';
import { triggerSOS } from '../services/api';
import { getCurrentLocation } from '../services/geolocation';
import '../styles/SOSButton.css';

function SOSButton({ contacts }) {
  const [isPressed, setIsPressed] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [message, setMessage] = useState('');
  const [notificationMethod, setNotificationMethod] = useState('both');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [location, setLocation] = useState(null);
  
  const pressTimer = useRef(null);
  const pressStartTime = useRef(null);

  const handlePressStart = () => {
    pressStartTime.current = Date.now();
    setIsPressed(true);
    
    pressTimer.current = setTimeout(() => {
      setShowModal(true);
      setIsPressed(false);
    }, 1500);
  };

  const handlePressEnd = () => {
    if (pressTimer.current) {
      clearTimeout(pressTimer.current);
    }
    
    const pressDuration = Date.now() - pressStartTime.current;
    if (pressDuration < 1500) {
      setIsPressed(false);
    }
  };

  const handleSendSOS = async () => {
    if (contacts.length === 0) {
      setError('Please add trusted contacts first');
      return;
    }

    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const locationData = await getCurrentLocation();
      setLocation(locationData);

      const response = await triggerSOS({
        latitude: locationData.latitude,
        longitude: locationData.longitude,
        message: message || 'Emergency! I need help immediately!',
        notificationMethod
      });

      if (response.success) {
        setSuccess(`SOS alert sent to ${response.contactsNotified} contact(s)`);
        setTimeout(() => {
          setShowModal(false);
          setMessage('');
          setSuccess('');
        }, 3000);
      } else {
        setError(response.message || 'Failed to send SOS');
      }
    } catch (err) {
      setError(err.message || 'Failed to send SOS alert');
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setShowModal(false);
    setMessage('');
    setError('');
    setSuccess('');
    setLocation(null);
  };

  return (
    <>
      <div className="sos-container">
        <button
          className={`sos-button ${isPressed ? 'pressed' : ''}`}
          onMouseDown={handlePressStart}
          onMouseUp={handlePressEnd}
          onMouseLeave={handlePressEnd}
          onTouchStart={handlePressStart}
          onTouchEnd={handlePressEnd}
        >
          <span className="sos-text">SOS</span>
          <span className="sos-instruction">Hold for 1.5s</span>
        </button>
        
        {isPressed && (
          <div className="press-indicator">
            <div className="press-progress"></div>
          </div>
        )}
      </div>

      {showModal && (
        <div className="sos-modal-overlay">
          <div className="sos-modal">
            <h2>⚠️ Emergency Alert</h2>
            
            {error && <div className="error-message">{error}</div>}
            {success && <div className="success-message">{success}</div>}

            {!success && (
              <>
                <p className="modal-info">
                  Your location will be shared with {contacts.length} trusted contact(s)
                </p>

                <textarea
                  placeholder="Optional message (e.g., I'm in danger, please help)"
                  value={message}
                  onChange={(e) => setMessage(e.target.value)}
                  rows="3"
                  disabled={loading}
                />

                <div className="notification-options">
                  <label>Send via:</label>
                  <div className="radio-group">
                    <label>
                      <input
                        type="radio"
                        value="sms"
                        checked={notificationMethod === 'sms'}
                        onChange={(e) => setNotificationMethod(e.target.value)}
                        disabled={loading}
                      />
                      SMS
                    </label>
                    <label>
                      <input
                        type="radio"
                        value="whatsapp"
                        checked={notificationMethod === 'whatsapp'}
                        onChange={(e) => setNotificationMethod(e.target.value)}
                        disabled={loading}
                      />
                      WhatsApp
                    </label>
                    <label>
                      <input
                        type="radio"
                        value="both"
                        checked={notificationMethod === 'both'}
                        onChange={(e) => setNotificationMethod(e.target.value)}
                        disabled={loading}
                      />
                      Both
                    </label>
                  </div>
                </div>

                <div className="modal-actions">
                  <button
                    onClick={handleSendSOS}
                    className="btn-send-sos"
                    disabled={loading}
                  >
                    {loading ? 'Sending...' : 'Send SOS Alert'}
                  </button>
                  <button
                    onClick={handleCancel}
                    className="btn-cancel"
                    disabled={loading}
                  >
                    Cancel
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
}

export default SOSButton;
